//! #190: the evaluation set in `fixtures/eval/` is well formed, big enough for
//! its consumers, exports a loadable `[embedder] related_pairs` file, and
//! carries nothing that looks like a secret or private data.
//!
//! The set is generated by `fixtures/eval/authoring/build.py`; see
//! `fixtures/eval/README.md`. Measuring it needs an embedder:
//! `cargo run --release --example eval_measure -- --help`.

#[path = "../examples/eval_measure/schema.rs"]
#[allow(dead_code)]
mod schema;

use std::path::{Path, PathBuf};

use lambo::embed::canary::{RelatedPair, MIN_RELATED_PAIRS};
use lambo::surface::limits::MAX_CONTENT_BYTES;

fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/eval")
}

fn set() -> schema::EvalSet {
    schema::load(&dir()).expect("the evaluation set loads")
}

#[test]
fn schema_holds() {
    let errors = schema::validate(&set(), MAX_CONTENT_BYTES);
    assert!(
        errors.is_empty(),
        "{} schema violations:\n{}",
        errors.len(),
        errors.join("\n")
    );
}

/// The sizes #190 asks for, per consumer: #87/#176 need at least
/// `MIN_RELATED_PAIRS` adjudicated related-but-distinct pairs; #190 asks for
/// 150 so that 100 survive adjudication, and 100 each of paraphrase and
/// unrelated pairs; #173 about 200 answerable queries; #174 at least 100
/// no-answer queries.
#[test]
fn sizes_meet_the_consumers() {
    let s = set();
    let count = |label: &str, adjudicated_only: bool| {
        s.pairs
            .iter()
            .filter(|p| p.label == label && (!adjudicated_only || p.adjudicated()))
            .count()
    };
    assert!(
        count("related_distinct", false) >= 150,
        "related_distinct pairs"
    );
    assert!(
        count("related_distinct", true) >= MIN_RELATED_PAIRS,
        "adjudicated related_distinct pairs"
    );
    assert!(count("paraphrase", true) >= 100, "paraphrase pairs");
    assert!(count("unrelated", true) >= 100, "unrelated pairs");
    let kind = |k: &str| {
        s.queries
            .iter()
            .filter(|q| q.kind == k && q.adjudicated())
            .count()
    };
    assert!(kind("answerable") >= 200, "answerable queries");
    assert!(kind("no_answer") >= 100, "no-answer queries");
    // Both splits are populated in every class, so a consumer can tune on
    // dev and report on held_out.
    for label in schema::LABELS {
        for split in schema::SPLITS {
            assert!(
                s.pairs.iter().any(|p| p.label == label && p.split == split),
                "no {label} pair in {split}"
            );
        }
    }
    for k in ["answerable", "no_answer"] {
        for split in schema::SPLITS {
            assert!(
                s.queries.iter().any(|q| q.kind == k && q.split == split),
                "no {k} query in {split}"
            );
        }
    }
}

/// The export is what `[embedder] related_pairs` reads: the canary's own
/// type, with unknown fields refused.
#[test]
fn export_loads_as_related_pairs() {
    let bytes = std::fs::read(dir().join("related_pairs.json")).unwrap();
    let pairs: Vec<RelatedPair> = serde_json::from_slice(&bytes).expect("canary format");
    assert!(pairs.len() >= MIN_RELATED_PAIRS, "{} pairs", pairs.len());
    let s = set();
    assert_eq!(pairs.len(), schema::expected_export(&s.pairs).len());
    // Items awaiting the owner's review never reach the export.
    for p in s.pairs.iter().filter(|p| !p.adjudicated()) {
        assert!(
            !pairs.iter().any(|e| e.a == p.a && e.b == p.b),
            "{} is under review",
            p.id
        );
    }
}

/// Every file under fixtures/eval (the authoring sources included) and
/// evidence/eval-set (the committed measurement runs).
fn files(dir: &Path, out: &mut Vec<PathBuf>) {
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            if path.file_name().is_some_and(|n| n != "__pycache__") {
                files(&path, out);
            }
        } else {
            out.push(path);
        }
    }
}

fn is_ipv4(token: &str) -> bool {
    let parts: Vec<&str> = token.split('.').collect();
    parts.len() == 4
        && parts
            .iter()
            .all(|p| !p.is_empty() && p.len() <= 3 && p.bytes().all(|b| b.is_ascii_digit()))
}

fn looks_like_email(token: &str) -> bool {
    let Some((user, host)) = token.split_once('@') else {
        return false;
    };
    let host = host.trim_end_matches(|c: char| !c.is_ascii_alphanumeric());
    !user.is_empty()
        && user
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"._%+-".contains(&b))
        && host.contains('.')
        && host
            .split('.')
            .all(|l| !l.is_empty() && l.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-'))
}

/// A guard, not a proof: the set was assembled from text already public in
/// this repository and the published, redacted lambo-paper results (see the
/// README's hygiene section). This keeps a later edit from adding a home
/// directory, an address, a private IP, a key or a token.
#[test]
fn nothing_private_or_secret() {
    const MARKERS: [&str; 16] = [
        "/Users/",
        "/home/",
        "C:\\Users",
        "PRIVATE KEY",
        "ghp_",
        "gho_",
        "github_pat_",
        "xoxb-",
        "xoxp-",
        "AKIA",
        "AIza",
        "sk-ant-",
        "sk-proj-",
        "Bearer ",
        "password=",
        "[REDACTED",
    ];
    let mut found = Vec::new();
    let mut all = Vec::new();
    files(&dir(), &mut all);
    // The committed measurement runs quote the embedder's identity.
    files(
        &std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("evidence/eval-set"),
        &mut all,
    );
    assert!(
        all.len() > 4,
        "the hygiene guard found too few files to scan"
    );
    for path in all {
        let Ok(text) = std::fs::read_to_string(&path) else {
            continue;
        };
        let name = path
            .strip_prefix(env!("CARGO_MANIFEST_DIR"))
            .unwrap_or(&path)
            .display()
            .to_string();
        // The extractor's own code names the redaction marker it drops.
        let code = path.extension().is_some_and(|e| e == "py");
        for m in MARKERS {
            if text.contains(m) && !(code && m == "[REDACTED") {
                found.push(format!("{name}: {m:?}"));
            }
        }
        for token in text.split(|c: char| c.is_whitespace() || "\"'`()[]{}<>,;|:/=".contains(c)) {
            let t = token.trim_matches(|c: char| c == '.' || c == ':');
            if is_ipv4(t) && t != "127.0.0.1" && t != "0.0.0.0" {
                found.push(format!("{name}: IP address {t}"));
            }
            if looks_like_email(t) {
                found.push(format!("{name}: address {t}"));
            }
        }
    }
    assert!(
        found.is_empty(),
        "possible private data:\n{}",
        found.join("\n")
    );
}
